# In production, SECRET_KEY must be set explicitly (via environment, .kamal/secrets,
# or auto-generated by docker-entrypoint.sh). Override base.py's random default
# so we fail loudly if it's truly missing.
SECRET_KEY = config("SECRET_KEY")

DEBUG = False

ALLOWED_HOSTS = config("ALLOWED_HOSTS", cast=Csv())

# Database
# SQLite is the default - stored in /app/data/ which is mounted as a volume
# This means the database persists across container rebuilds and deploys
# VPS backups automatically include your database - simple and effective
# SQLITE_OPTIONS (from base.py) enables WAL mode, IMMEDIATE transactions,
# and performance PRAGMAs to prevent "database is locked" errors
# See /help/database-sqlite/ for more on why SQLite works great in production
DATABASES = {
    "default": {
        "ENGINE": "django.db.backends.sqlite3",
        "NAME": config("DATABASE_PATH", default="/app/data/db.sqlite3"),
        "OPTIONS": SQLITE_OPTIONS,  # noqa: F405
    }
}

# CW credentials encryption key. It encrypts operators' QRZ/eQSL passwords at
# rest, so it MUST persist across rebuilds — default it onto the /app/data
# volume (alongside db.sqlite3). Generating a new key can't read data encrypted
# with the old one, so back this file up with the database. (fieldcrypto.py)
CW_CREDENTIALS_KEY_FILE = config(
    "CW_CREDENTIALS_KEY_FILE", default="/app/data/.cw_credentials_key"
)

