# Security settings
SECURE_BROWSER_XSS_FILTER = True
SECURE_CONTENT_TYPE_NOSNIFF = True
X_FRAME_OPTIONS = "DENY"
SECURE_HSTS_SECONDS = 31536000
SECURE_HSTS_INCLUDE_SUBDOMAINS = True
SECURE_HSTS_PRELOAD = True

# HTTPS settings
# CSRF_TRUSTED_ORIGINS is required for HTTPS behind a proxy (like kamal-proxy)
CSRF_TRUSTED_ORIGINS = config(
    "CSRF_TRUSTED_ORIGINS",
    default="",
    cast=lambda v: [s.strip() for s in v.split(",") if s.strip()] if v else [],
)

# kamal-proxy handles HTTPS redirect, so SECURE_SSL_REDIRECT should be False
# to avoid breaking internal health checks (which use HTTP)
SECURE_SSL_REDIRECT = config("SECURE_SSL_REDIRECT", default=False, cast=bool)
SESSION_COOKIE_SECURE = config("SESSION_COOKIE_SECURE", default=True, cast=bool)
CSRF_COOKIE_SECURE = config("CSRF_COOKIE_SECURE", default=True, cast=bool)

# Trust the proxy's X-Forwarded-For for client IP resolution (activity log +
# axes login lockout). Behind a reverse proxy REMOTE_ADDR is the proxy, so
# every request shares one address and axes' IP-based lockout is neutered;
# reading the real client from the header restores it. Defaults on here for the
# blessed kamal-proxy deployment. Set TRUST_PROXY_HEADERS=false if you deploy
# WITHOUT a trusted proxy in front, so client IPs come from the non-spoofable
# REMOTE_ADDR. See apps/smallstack/client_ip.py.
TRUST_PROXY_HEADERS = config("TRUST_PROXY_HEADERS", default=True, cast=bool)

# The same proxy-trust decision applies to the forwarded protocol. kamal-proxy
# terminates TLS and forwards to the container over HTTP with
# ``X-Forwarded-Proto: https``. Without trusting it, ``request.is_secure()`` is
# False behind the proxy and Django builds ``http://`` absolute URLs — feed
# self-links, sitemaps, and the links in password-reset / invite emails all go
# out as http. Trust the header only when TRUST_PROXY_HEADERS is on: a container
# reachable *only* through the proxy can't have it spoofed, whereas a
# directly-exposed deploy (flag off) must not trust a client-supplied header.
if TRUST_PROXY_HEADERS:
    SECURE_PROXY_SSL_HEADER = ("HTTP_X_FORWARDED_PROTO", "https")

# Backups — store on the mounted data volume so they survive deploys
BACKUP_DIR = config("BACKUP_DIR", default="/app/data/backups")

# Logging configuration
#
# File logging: Set LOG_FILE to a path to also write logs to a file.
# Uses RotatingFileHandler: 5 MB max per file, keeps 5 backups.
# Example: LOG_FILE=/app/data/logs/app.log
# The directory must exist — Django won't create it for you.
LOG_FILE = config("LOG_FILE", default="")

LOGGING = {
    "version": 1,
    "disable_existing_loggers": False,
    "filters": {
        # Puts request_id/trace_id on every record. Attached to handlers, not
        # loggers, so it also sees records propagated up from child loggers.
        "request_context": {
            "()": "apps.smallstack.logging.RequestContextFilter",
        },
    },
    "formatters": {
        # Real JSON via json.dumps — quotes, newlines and backslashes in a
        # message are escaped, tracebacks land in an "exc" field instead of
        # spilling raw lines after the closing brace, and extra={...} fields
        # from call sites are preserved under "extra".
        "json": {
            "()": "apps.smallstack.logging.JSONFormatter",
        },
    },
    "handlers": {
        "console": {
            "class": "logging.StreamHandler",
            "formatter": "json",
            "filters": ["request_context"],
        },
    },
    "root": {
        "handlers": ["console"],
        "level": "WARNING",
    },
    "loggers": {
        "django": {
            "handlers": ["console"],
            "level": "WARNING",
            "propagate": False,
        },
        "django.request": {
            "handlers": ["console"],
            "level": "ERROR",
            "propagate": False,
        },
        "django.security": {
            "handlers": ["console"],
            "level": "WARNING",
            "propagate": False,
        },
        "apps": {
            "handlers": ["console"],
            "level": "INFO",
            "propagate": False,
        },
        "smallstack.mcp": {
            "handlers": ["console"],
            "level": "INFO",
            "propagate": False,
        },
    },
}

# Add file handler when LOG_FILE is set
if LOG_FILE:
    LOGGING["handlers"]["file"] = {
        "class": "logging.handlers.RotatingFileHandler",
        "filename": LOG_FILE,
        "maxBytes": 5 * 1024 * 1024,  # 5 MB
        "backupCount": 5,
        "formatter": "json",
        "filters": ["request_context"],
    }
    # Add file handler to all loggers
    LOGGING["root"]["handlers"].append("file")
    for logger_config in LOGGING["loggers"].values():
        logger_config["handlers"].append("file")

# Database log capture — makes logs readable from inside the app when the log
# stream isn't reachable (locked-down container, managed platform with no
# shell). Baseline is WARNING; `manage.py log_capture start --level DEBUG
# --minutes 15` turns it up temporarily. Settings live in smallstack.py.
if TELEMETRY_LOG_CAPTURE_ENABLED:  # noqa: F405
    LOGGING["handlers"]["db"] = {
        "()": "apps.telemetry.handlers.DatabaseLogHandler",
        "level": TELEMETRY_LOG_LEVEL,  # noqa: F405
        "queue_size": TELEMETRY_LOG_QUEUE_SIZE,  # noqa: F405
        "filters": ["request_context"],
    }
    # Every logger, because they all set propagate=False — a handler on root
    # alone would only ever see records nothing else claimed.
    LOGGING["root"]["handlers"].append("db")
    for logger_config in LOGGING["loggers"].values():
        logger_config["handlers"].append("db")

